#include <iostream>

int main() {
    // Direct initialization and copy initialization
    int a = 10;
    int b(20);
    int c{30};

    // Chained assignment
    a = b = c = 50;

    // Assignment expression evaluated inside output stream
    int result;
    std::cout << (result = a + 5) << std::endl;
    std::cout << a << " " << b << " " << c << " " << result << std::endl;

    return 0;
}

#include <iostream>
#include <iomanip>

int main() {
    // Check Point 2.7 & 2.8 implementation
    const int SIZE = 20;
    const double KILOMETERS_PER_MILE = 1.609;

    double miles = 100.0;
    double kilometers = miles * KILOMETERS_PER_MILE;

    // Numeric storage demonstration
    unsigned short max_ushort = 65535;
    float f_val = 3.14159f;
    double d_val = 3.141592653589793;

    std::cout << "Size: " << SIZE << std::endl;
    std::cout << "Kilometers: " << kilometers << std::endl;
    std::cout << "Max unsigned short: " << max_ushort << std::endl;
    std::cout << std::fixed << std::setprecision(5);
    std::cout << "Float: " << f_val << std::endl;
    std::cout << "Double: " << d_val << std::endl;

    return 0;
}
